  "inlineSchema": "// ========================================\n// LookForHome – Schéma Prisma\n// ========================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ---------- Utilisateurs ----------\nenum Role {\n  LANDLORD\n  TENANT\n  ADMIN\n}\n\nenum Gender {\n  HOMME\n  FEMME\n  AUTRE\n}\n\nmodel User {\n  id        String   @id @default(cuid())\n  name      String\n  firstName String? // utilisé surtout pour Admin\n  email     String   @unique\n  password  String // hashé avec bcrypt\n  gender    Gender?\n  whatsapp  String\n  role      Role\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  listings      Listing[]         @relation(\"LandlordListings\") // bailleur\n  submissions   Listing[]         @relation(\"SubmittedBy\") // soumissions bailleur\n  unlocked      UnlockedListing[]\n  favorites     Favorite[]\n  visits        Visit[]\n  notifications NotificationLog[]\n\n  @@map(\"users\")\n}\n\n// ---------- Types de logement ----------\nenum HousingType {\n  CHAMBRE_MODERNE\n  CHAMBRE_SIMPLE\n  STUDIO_MODERNE\n  STUDIO_SIMPLE\n  APPARTEMENT_MODERNE\n  APPARTEMENT_SIMPLE\n  LOCAL_COMMERCE\n  LOCAL_AUTRE\n}\n\nenum ListingStatus {\n  PENDING // soumission bailleur en attente\n  PUBLISHED // publié par admin\n  REJECTED\n  ARCHIVED\n}\n\nmodel Listing {\n  id             String        @id @default(cuid())\n  type           HousingType\n  bedrooms       Int? // 1-10 (studio / appartement)\n  bathrooms      Int? // 1-5\n  livingRooms    Int? // 1-5\n  hasWater       Boolean       @default(true)\n  hasElectricity Boolean       @default(true)\n  neighborhood   String\n  description    String        @db.Text\n  visitPrice     Int           @default(2000) // FCFA\n  status         ListingStatus @default(PENDING)\n  images         String[] // URLs (Cloudinary / S3)\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime      @updatedAt\n  publishedAt    DateTime?\n\n  // Qui a soumis (bailleur)\n  submittedById String?\n  submittedBy   User?   @relation(\"SubmittedBy\", fields: [submittedById], references: [id])\n\n  // Qui a publié (admin) ou propriétaire final\n  landlordId String?\n  landlord   User?   @relation(\"LandlordListings\", fields: [landlordId], references: [id])\n\n  // Relations\n  unlockedBy UnlockedListing[]\n  favorites  Favorite[]\n  visits     Visit[]\n\n  @@map(\"listings\")\n}\n\n// ---------- Déblocages (visite payée) ----------\nmodel UnlockedListing {\n  id         String   @id @default(cuid())\n  userId     String\n  listingId  String\n  unlockedAt DateTime @default(now())\n\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  listing Listing @relation(fields: [listingId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, listingId]) // un utilisateur ne paie qu'une fois\n  @@map(\"unlocked_listings\")\n}\n\n// ---------- Favoris ----------\nmodel Favorite {\n  id        String   @id @default(cuid())\n  userId    String\n  listingId String\n  createdAt DateTime @default(now())\n\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  listing Listing @relation(fields: [listingId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, listingId])\n  @@map(\"favorites\")\n}\n\n// ---------- Historique des visites (paiements) ----------\nmodel Visit {\n  id            String   @id @default(cuid())\n  userId        String\n  listingId     String\n  amount        Int // FCFA\n  paymentMethod String? // MTN_MOMO | ORANGE_MONEY | CARD\n  transactionId String? // ID retourné par Campay / CamerPay\n  status        String   @default(\"SUCCESS\") // SUCCESS | FAILED | PENDING\n  createdAt     DateTime @default(now())\n\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  listing Listing @relation(fields: [listingId], references: [id], onDelete: Cascade)\n\n  @@map(\"visits\")\n}\n\n// ---------- Logs de notifications ----------\nmodel NotificationLog {\n  id        String   @id @default(cuid())\n  userId    String?\n  channel   String // SMS | WHATSAPP\n  message   String   @db.Text\n  status    String   @default(\"SENT\") // SENT | FAILED\n  createdAt DateTime @default(now())\n\n  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@map(\"notification_logs\")\n}\n\n// ---------- Paramètres globaux (singleton) ----------\nmodel Setting {\n  id                Int      @id @default(1)\n  defaultVisitPrice Int      @default(2000)\n  supportWhatsapp   String   @default(\"+2376XXXXXXXX\")\n  supportSms        String   @default(\"+2376XXXXXXXX\")\n  adminCode         String   @default(\"LFH-ADMIN-2026\")\n  updatedAt         DateTime @updatedAt\n\n  @@map(\"settings\")\n}\n",
